import { test, expect } from '@playwright/test';
import { prepareReadOnly, openResults, categoryUrl, stripOpensFilters, CATEGORY } from './search-cta.helpers';

test.use({ serviceWorkers: 'block' });

test('Категория: полоса «חפש עסק» после прокрутки, в окне фильтров выбранная категория сохранена #1a3a08 #839121 @android @prod-safe', async ({ page, context }) => {
  await prepareReadOnly(context);
  await openResults(page, categoryUrl());
  const url = page.url();
  const dialog = await stripOpensFilters(page);
  await expect(dialog, `в окне выбрана категория «${CATEGORY}»`).toContainText(CATEGORY);
  expect(page.url(), 'адрес страницы (категория) не изменился').toBe(url);
});
